  "a_sentences": [
    {
      "a_text": "Selon l'art. 94 LTF, le recours pour déni de justice et retard injustifié est recevable si la juridiction saisie s'abstient de rendre une décision sujette à recours ou tarde à le faire.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle que l'autorité viole l'art. 29 al. 1 Cst. lorsqu'elle ne rend pas sa décision dans un délai raisonnable, apprécié selon la nature de l'affaire et les circonstances.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "L'art. 29 al. 1 Cst. garantit à toute personne le droit à ce que sa cause soit jugée dans un délai raisonnable.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Pour se plaindre avec succès d'un retard injustifié, la partie doit avoir vainement interpellé l'autorité afin qu'elle statue à bref délai.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale peut communiquer aux parties le dispositif d'un arrêt avant de leur transmettre la décision motivée, cette pratique n'étant pas réservée aux seules situations urgentes.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La partie doit avoir vainement interpellé l'autorité concernée pour que celle-ci statue à bref délai.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le grief de retard injustifié ne peut pas prospérer.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le recours est rejeté dans la mesure de sa recevabilité.",
      "b_propositions": ["P8"]
    }
  ]
}
